/// virtual_tour : ""

class Gallery {
  Gallery({
      List<String> images, 
      List<dynamic> videos, 
      String virtualTour,}){
    _images = images;
    _videos = videos;
    _virtualTour = virtualTour;
}

  Gallery.fromJson(dynamic json) {
    _images = json['images'] != null ? json['images'].cast<String>() : [];
    if (json['videos'] != null) {
      _videos = [];
      json['videos'].forEach((v) {
        _videos.add(Dynamic.fromJson(v));
      });
    }
    _virtualTour = json['virtual_tour'];
  }
  List<String> _images;
  List<dynamic> _videos;
  String _virtualTour;
Gallery copyWith({  List<String> images,
  List<dynamic> videos,
  String virtualTour,
}) => Gallery(  images: images ?? _images,
  videos: videos ?? _videos,
  virtualTour: virtualTour ?? _virtualTour,
);
  List<String> get images => _images;
  List<dynamic> get videos => _videos;
  String get virtualTour => _virtualTour;

  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{};
    map['images'] = _images;
    if (_videos != null) {
      map['videos'] = _videos.map((v) => v.toJson()).toList();
    }
    map['virtual_tour'] = _virtualTour;
    return map;
  }

}

