class Reviews {
  Reviews({
      Ratings ratings, 
      List<dynamic> latestReviews, 
      num totalVerifiedReviews,}){
    _ratings = ratings;
    _latestReviews = latestReviews;
    _totalVerifiedReviews = totalVerifiedReviews;
}

  Reviews.fromJson(dynamic json) {
    _ratings = json['ratings'] != null ? Ratings.fromJson(json['ratings']) : null;
    if (json['latest_reviews'] != null) {
      _latestReviews = [];
      json['latest_reviews'].forEach((v) {
        _latestReviews.add(Dynamic.fromJson(v));
      });
    }
    _totalVerifiedReviews = json['total_verified_reviews'];
  }
  Ratings _ratings;
  List<dynamic> _latestReviews;
  num _totalVerifiedReviews;
Reviews copyWith({  Ratings ratings,
  List<dynamic> latestReviews,
  num totalVerifiedReviews,
}) => Reviews(  ratings: ratings ?? _ratings,
  latestReviews: latestReviews ?? _latestReviews,
  totalVerifiedReviews: totalVerifiedReviews ?? _totalVerifiedReviews,
);
  Ratings get ratings => _ratings;
  List<dynamic> get latestReviews => _latestReviews;
  num get totalVerifiedReviews => _totalVerifiedReviews;

  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{};
    if (_ratings != null) {
      map['ratings'] = _ratings.toJson();
    }
    if (_latestReviews != null) {
      map['latest_reviews'] = _latestReviews.map((v) => v.toJson()).toList();
    }
    map['total_verified_reviews'] = _totalVerifiedReviews;
    return map;
  }

}

